#!/usr/bin/env node
/* Stamp www/js/version.js with the bundle version (short git SHA, or the
 * BUNDLE_VERSION env override) and the native version pulled out of
 * config.xml's <widget version="...">.
 *
 * The values are read by www/js/ota.js at boot:
 *   - __BUNDLE_VERSION__ is compared against the remote manifest to decide
 *     whether a downloaded OTA bundle is newer than what shipped in the APK.
 *   - __APK_NATIVE_VERSION__ gates bundles that need a newer native shell:
 *     an OTA manifest can set minNativeVersion to refuse loading on an APK
 *     that's too old.
 *
 * Two invocation modes:
 *
 *   1) Cordova hooks (config.xml <hook type="before_prepare" /> +
 *      <hook type="after_prepare" />). The before_prepare pass stamps real
 *      values into www/js/version.js so `cordova prepare` copies them into
 *      platforms/android/app/src/main/assets/www/. The after_prepare pass
 *      restores the committed stub, mirroring the dance build-preloaded.js
 *      does for preload.js. Net effect: the APK gets the real values, the
 *      working tree stays clean.
 *
 *   2) Direct CLI (node scripts/stamp-bundle-version.js). Used by the CI
 *      workflow publish-web-bundle.yml to stamp the OTA bundle's copy of
 *      version.js with the bundle's own SHA before zipping. No restore.
 */
'use strict';

const fs   = require('node:fs');
const path = require('node:path');
const { spawnSync } = require('node:child_process');

const ROOT      = path.resolve(__dirname, '..');
const CONFIG    = path.join(ROOT, 'config.xml');
const VERSION_F = path.join(ROOT, 'www', 'js', 'version.js');

const STUB =
`// Bundle + native version metadata, stamped at build time by
// scripts/stamp-bundle-version.js (run as a Cordova \`before_prepare\` hook).
//
//   __BUNDLE_VERSION__       Short git SHA (or BUNDLE_VERSION env override)
//                            identifying the www/ contents shipped in this
//                            APK. Compared against the remote OTA manifest
//                            to decide whether a downloaded bundle is newer.
//   __APK_NATIVE_VERSION__   Reads from the <widget version="..."> in
//                            config.xml. An OTA bundle declaring a higher
//                            minNativeVersion than this is refused so old
//                            APKs don't load bundles needing native plugins
//                            they don't have.
//   __BUNDLE_STAMPED_AT__    ISO timestamp the stamp ran. Diagnostics only.
//
// This file is overwritten on every build. The committed contents are a
// no-op stub; running \`npm run build\` (or anything else that triggers
// \`cordova prepare\`) replaces them with real values.
window.__BUNDLE_VERSION__     = 'dev';
window.__APK_NATIVE_VERSION__ = '0.0.0';
window.__BUNDLE_STAMPED_AT__  = '';
`;

function readNativeVersion() {
  try {
    const xml = fs.readFileSync(CONFIG, 'utf8');
    const m = xml.match(/<widget\b[^>]*\sversion=("|')([^"']+)\1/);
    return m ? m[2] : '0.0.0';
  } catch (_) {
    return '0.0.0';
  }
}

function readBundleVersion() {
  const env = (process.env.BUNDLE_VERSION || '').trim();
  if (env) return env;
  try {
    const r = spawnSync('git', ['rev-parse', '--short', 'HEAD'], { cwd: ROOT });
    if (r.status === 0) {
      const sha = String(r.stdout).trim();
      if (sha) return sha;
    }
  } catch (_) { /* ignore */ }
  return 'dev';
}

function stamp() {
  const bundleVersion = readBundleVersion();
  const nativeVersion = readNativeVersion();
  const stampedAt = new Date().toISOString();
  const body =
`// AUTO-GENERATED by scripts/stamp-bundle-version.js (Cordova before_prepare
// hook). Edit the source values via BUNDLE_VERSION env or config.xml's
// <widget version="..."> -- not this file. See www/js/ota.js for how these
// fields gate OTA updates.
window.__BUNDLE_VERSION__     = ${JSON.stringify(bundleVersion)};
window.__APK_NATIVE_VERSION__ = ${JSON.stringify(nativeVersion)};
window.__BUNDLE_STAMPED_AT__  = ${JSON.stringify(stampedAt)};
`;
  fs.writeFileSync(VERSION_F, body);
  console.log(`stamp-bundle-version: stamped bundle=${bundleVersion} native=${nativeVersion}`);
}

function restoreStub() {
  fs.writeFileSync(VERSION_F, STUB);
  console.log('stamp-bundle-version: restored stub');
}

function hookType(ctx) {
  if (!ctx) return null;
  // Cordova passes the hook name via ctx.hook (e.g. 'before_prepare').
  return ctx.hook || (ctx.opts && ctx.opts.hook) || null;
}

if (require.main === module) {
  stamp();
} else {
  module.exports = function (ctx) {
    const hook = hookType(ctx);
    if (hook === 'after_prepare') restoreStub();
    else stamp();
  };
}
